import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("./server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);

import { emit } from "@/lib/event-bus";
import { exportActivitySchema } from "@/schemas/activity";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  exportActivity,
  listActivity,
  readActivityRange,
  registerActivityListeners,
} from "@/server/services/activity-service";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
import type { Tenant } from "./server/_support/fixtures";
import type { IsoTimestamp, OrgId, ProjectId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let detach: Unsubscribe;
let otherProjectId: ProjectId;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("scratch", "growth");
  detach = registerActivityListeners();
  const other = await projectRepo.insertProject({
    orgId: tenant.org.id,
    name: "Other",
    slug: "other",
    key: "OTH",
    description: null,
    visibility: "org",
    leadId: tenant.userIds.owner,
    color: "#000000",
    targetDate: null,
  });
  otherProjectId = other.id;
});

afterAll(() => {
  detach();
  cleanup();
});

describe("scratch audit verification", () => {
  it("files comment, status and assignment entries under the issue's project", async () => {
    const { actors, userIds, project, org } = tenant;
    const issue = await issueService.createIssue(
      actors.admin,
      issueInput(org.id, project.id, { title: "Tracked" }),
    );
    const otherIssue = await issueService.createIssue(
      actors.admin,
      issueInput(org.id, otherProjectId, { title: "Elsewhere" }),
    );

    await issueService.changeIssueStatus(actors.member, {
      orgId: org.id,
      issueId: issue.id,
      status: "in_progress",
    });
    await issueService.assignIssue(actors.admin, {
      orgId: org.id,
      issueId: issue.id,
      assigneeId: userIds.viewer,
    });
    const comment = await commentService.createComment(actors.member, {
      orgId: org.id,
      issueId: issue.id,
      body: "first",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.updateComment(actors.member, {
      orgId: org.id,
      commentId: comment.id,
      body: "edited",
    });
    await commentService.deleteComment(actors.member, {
      orgId: org.id,
      commentId: comment.id,
    });
    await commentService.createComment(actors.member, {
      orgId: org.id,
      issueId: otherIssue.id,
      body: "elsewhere",
      parentId: null,
      mentionedUserIds: [],
    });

    const feed = await listActivity(actors.member, {
      orgId: org.id,
      projectId: project.id,
      limit: 100,
      cursor: null,
    });
    const actions = feed.items.map((e) => e.action).sort();
    expect(actions).toEqual(
      expect.arrayContaining([
        "issue.created",
        "issue.status_changed",
        "issue.assigned",
        "comment.created",
        "comment.updated",
        "comment.deleted",
      ]),
    );
    expect(feed.items.every((e) => e.projectId === project.id)).toBe(true);

    const assigned = feed.items.find((e) => e.action === "issue.assigned");
    expect(assigned?.actorId).toBe(userIds.admin);
    expect(assigned?.metadata).toMatchObject({ assigneeId: userIds.viewer });

    const status = feed.items.find((e) => e.action === "issue.status_changed");
    expect(status?.metadata).toMatchObject({ from: "backlog", to: "in_progress" });
  });

  it("stamps entries with the event's own time and includes both range ends", async () => {
    const stamp = "2020-01-01T00:00:00.000Z" as IsoTimestamp;
    await emit("issue.archived", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.admin,
      occurredAt: stamp,
      issueId: "backdated-issue" as never,
      projectId: tenant.project.id,
    });

    const exact = await readActivityRange(tenant.org.id, {
      since: stamp,
      until: stamp,
    });
    expect(exact).toHaveLength(1);
    expect(exact[0]).toMatchObject({ action: "issue.archived", occurredAt: stamp });
  });

  it("exports every entry across pages with no duplicates, newest first", async () => {
    for (let i = 0; i < 230; i += 1) {
      await emit("flag.toggled", {
        orgId: tenant.org.id,
        actorId: tenant.userIds.admin,
        occurredAt: new Date(Date.UTC(2021, 0, 1, 0, 0, i)).toISOString() as IsoTimestamp,
        flag: "csv_export" as never,
        enabled: i % 2 === 0,
      });
    }

    const range = {
      since: "2000-01-01T00:00:00.000Z" as IsoTimestamp,
      until: "2100-01-01T00:00:00.000Z" as IsoTimestamp,
    };
    const everything = await readActivityRange(tenant.org.id, range);
    const total = await activityRepo.listActivity({
      orgId: tenant.org.id,
      limit: 1,
      cursor: null,
    });

    expect(everything).toHaveLength(total.total);
    expect(new Set(everything.map((e) => e.id)).size).toBe(everything.length);
    const stamps = everything.map((e) => e.occurredAt);
    expect([...stamps].sort().reverse()).toEqual(stamps);

    const json = JSON.parse(
      await exportActivity(tenant.actors.admin, {
        orgId: tenant.org.id,
        since: range.since,
        until: range.until,
        format: "json",
      }),
    ) as Array<{ metadata: Record<string, unknown> }>;
    expect(json).toHaveLength(total.total);
    expect(json.some((e) => e.metadata.from === "backlog")).toBe(true);
  });

  it("refuses a range that ends before it starts", () => {
    const parsed = exportActivitySchema.safeParse({
      orgId: tenant.org.id as OrgId,
      since: "2021-01-02T00:00:00Z",
      until: "2021-01-01T00:00:00Z",
      format: "json",
    });
    expect(parsed.success).toBe(false);

    return expect(
      exportActivity(tenant.actors.admin, {
        orgId: tenant.org.id,
        since: "2021-01-02T00:00:00.000Z" as IsoTimestamp,
        until: "2021-01-01T00:00:00.000Z" as IsoTimestamp,
        format: "json",
      }),
    ).rejects.toThrow();
  });

  it("normalises equivalent instants written in different forms", () => {
    const parsed = exportActivitySchema.parse({
      orgId: tenant.org.id,
      since: "2021-01-01T00:00:00Z",
      until: "2021-01-01T00:00:00Z",
    });
    expect(parsed.since).toBe("2021-01-01T00:00:00.000Z");
    expect(parsed.until).toBe("2021-01-01T00:00:00.000Z");
  });
});

